import{_ as a,o as i,c as e,a2 as h}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"配置 shell 命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/shell-aliases.md","filePath":"zh/shell-aliases.md"}'),t={name:"zh/shell-aliases.md"};function l(n,s,d,o,p,c){return i(),e("div",null,[...s[0]||(s[0]=[h(`<h1 id="配置-shell-命令" tabindex="-1">配置 shell 命令 <a class="header-anchor" href="#配置-shell-命令" aria-label="Permalink to &quot;配置 shell 命令&quot;">​</a></h1><p>Pi 为每条 Bash 命令启动一个独立的非交互式 shell 进程。非交互式 Bash 默认不展开别名（alias），通常也不会像交互式终端那样加载相同的启动文件。</p><p>使用 <code>shellPath</code> 选择 Bash 可执行文件，使用 <code>shellCommandPrefix</code> 在每条命令前执行初始化。</p><h2 id="了解-pi-使用哪个-shell" tabindex="-1">了解 Pi 使用哪个 shell <a class="header-anchor" href="#了解-pi-使用哪个-shell" aria-label="Permalink to &quot;了解 Pi 使用哪个 shell&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令来源</th><th>Shell</th></tr></thead><tbody><tr><td>模型调用内置的 <code>bash</code> 工具</td><td>Pi 解析出的 Bash 可执行文件</td></tr><tr><td>你输入 <code>!command</code> 或 <code>!!command</code></td><td>同一个解析出的 Bash 可执行文件</td></tr><tr><td>模型调用可选的 <code>powershell</code> 工具</td><td>PowerShell 7（<code>pwsh.exe</code>）或 Windows PowerShell</td></tr><tr><td>扩展提供或替换了 shell 工具</td><td>该扩展实现的操作</td></tr></tbody></table><p>Pi 通常以 <code>bash -c</code> 调用 Bash。在 Unix 系统上，它先使用 <code>/bin/bash</code>，然后是 <code>PATH</code> 上的 <code>bash</code>，最后在 Bash 不可用时使用 <code>sh</code>。原生 Windows 先检查配置的路径，然后是 Git Bash，最后是 <code>PATH</code> 上的 <code>bash.exe</code>。</p><h2 id="选择-bash-可执行文件" tabindex="-1">选择 Bash 可执行文件 <a class="header-anchor" href="#选择-bash-可执行文件" aria-label="Permalink to &quot;选择 Bash 可执行文件&quot;">​</a></h2><p>当 Pi 需要使用特定可执行文件时，在 <code>~/.pi/agent/settings.json</code> 中设置 <code>shellPath</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.local/bin/bash&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Windows 上使用正斜杠或转义反斜杠：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cygwin64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bash.exe&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>更改设置后运行 <code>/reload</code>。原生 Windows 的默认值见<a href="./windows.html">在 Windows 上运行 Pi</a>。</p><h2 id="在每条-bash-命令前执行初始化" tabindex="-1">在每条 Bash 命令前执行初始化 <a class="header-anchor" href="#在每条-bash-命令前执行初始化" aria-label="Permalink to &quot;在每条 Bash 命令前执行初始化&quot;">​</a></h2><p>设置 <code>shellCommandPrefix</code> 可为内置 <code>bash</code> 工具以及用户输入的 <code>!</code> 或 <code>!!</code> 命令前置 shell 初始化：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellCommandPrefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;export CI=1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pi 用换行符连接前缀和请求的命令。前缀会在每条命令前重新执行，因此要保持简短并避免交互式提示。</p><h2 id="启用-bash-别名" tabindex="-1">启用 Bash 别名 <a class="header-anchor" href="#启用-bash-别名" aria-label="Permalink to &quot;启用 Bash 别名&quot;">​</a></h2><p>将 Pi 需要的别名存放在一个 Bash 兼容的文件中，而不是解析整个交互式 shell 配置。</p><p>创建 <code>~/.bash_aliases</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ll</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ls -la&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;git status --short&#39;</span></span></code></pre></div><p>然后配置 Pi 启用别名展开并加载该文件：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellCommandPrefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shopt -s expand_aliases</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">source ~/.bash_aliases&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>运行 <code>/reload</code>，然后通过 Pi 验证别名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!ll</span></span></code></pre></div><p>该命令应产生与 <code>ls -la</code> 相同的列表。</p><p>别名必须使用 Bash 兼容语法。不要把任意的 <code>.zshrc</code> source 进 Bash，因为 zsh 的选项、函数和插件在其中可能无法解析或行为不正确。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><h3 id="前缀对-生效但对扩展工具不生效" tabindex="-1">前缀对 <code>!</code> 生效但对扩展工具不生效 <a class="header-anchor" href="#前缀对-生效但对扩展工具不生效" aria-label="Permalink to &quot;前缀对 \`!\` 生效但对扩展工具不生效&quot;">​</a></h3><p><code>shellCommandPrefix</code> 只配置 Pi 内置的 Bash 执行。替换 <code>bash</code> 工具或提供自己 shell 操作的扩展自行控制其初始化。请查阅该扩展的文档。</p><h3 id="找不到-shopt" tabindex="-1">找不到 <code>shopt</code> <a class="header-anchor" href="#找不到-shopt" aria-label="Permalink to &quot;找不到 \`shopt\`&quot;">​</a></h3><p>Pi 已回退到 <code>sh</code>，或 <code>shellPath</code> 指向了非 Bash 的 shell。安装 Bash，或将 <code>shellPath</code> 设为 Bash 可执行文件，再使用 <code>shopt</code> 等 Bash 特有的初始化。</p><h3 id="初始化命令等待输入" tabindex="-1">初始化命令等待输入 <a class="header-anchor" href="#初始化命令等待输入" aria-label="Permalink to &quot;初始化命令等待输入&quot;">​</a></h3><p>从 <code>shellCommandPrefix</code> 中移除交互式命令。前缀在每条 Bash 命令前的非交互式进程中运行。</p><p>完整设置定义见 <a href="./settings.html#shell">Shell 设置</a>。</p>`,34)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
